using System.ComponentModel.DataAnnotations;

namespace MyApi.Settings;

public class MySettings
{
    [Required]
    public string ApiUrl { get; set; } = string.Empty;

    [Range(1, 120)]
    public int TimeoutSeconds { get; set; } = 30;

    public FeatureFlags Features { get; set; } = new();
}

public class FeatureFlags
{
    public bool EnableNewCheckout { get; set; }
    public bool EnableBetaSearch { get; set; }
}

using Microsoft.Extensions.Options;
using MyApi.Settings;

var builder = WebApplication.CreateBuilder(args);

// Bind the "MySettings" section to MySettings and validate on startup.
builder.Services
    .AddOptions<MySettings>()
    .Bind(builder.Configuration.GetSection("MySettings"))
    .ValidateDataAnnotations()
    .ValidateOnStart();

var app = builder.Build();
app.Run();

// --- Consumer ---
public class HomeController : ControllerBase
{
    private readonly MySettings _settings;

    public HomeController(IOptions<MySettings> options)
    {
        _settings = options.Value;
    }

    [HttpGet("config")]
    public IActionResult GetConfig() => Ok(new
    {
        _settings.ApiUrl,
        _settings.TimeoutSeconds,
        _settings.Features.EnableNewCheckout
    });
}

using Microsoft.Extensions.Options;

public class FeatureWatcher : IDisposable
{
    private readonly IDisposable? _changeTracker;

    public FeatureWatcher(IOptionsMonitor<MySettings> monitor)
    {
        _changeTracker = monitor.OnChange(settings =>
        {
            Console.WriteLine(
                "Config reloaded — EnableNewCheckout = {0}",
                settings.Features.EnableNewCheckout);
        });
    }

    public void Dispose() => _changeTracker?.Dispose();
}
